<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import http from '@/api/http';import { useAuthStore } from '@/stores/auth';import { ElMessage } from 'element-plus';import type { Dict } from '@/types'
const auth=useAuthStore(),rows=ref<Dict[]>([]),keyword=ref(''),dialog=ref(false),form=reactive<Dict>({code:'',name:'',unifiedCreditCode:'',level:'B',status:'QUALIFIED',contactName:'',contactPhone:'',email:'',address:''})
async function load(){rows.value=await http.get('/suppliers',{params:{keyword:keyword.value}})}async function save(){await http.post('/suppliers',form);ElMessage.success('供应商已创建');dialog.value=false;load()}onMounted(load)
const statusName:Dict={PENDING:'待审核',QUALIFIED:'合格',SUSPENDED:'暂停',BLACKLISTED:'黑名单'}
</script>
<template><div class="page"><div class="page-head"><div><h1>供应商管理</h1><p>供应商准入、分级、资质与绩效档案</p></div><el-button v-if="auth.can('supplier:edit')" type="primary" @click="dialog=true">新增供应商</el-button></div><div class="panel panel-pad"><div class="toolbar"><el-input v-model="keyword" placeholder="供应商编码或名称" style="width:280px" @keyup.enter="load"/><el-button @click="load">查询</el-button></div><el-table :data="rows"><el-table-column prop="code" label="编码" width="130"/><el-table-column prop="name" label="供应商" min-width="220"/><el-table-column prop="level" label="等级" width="80"><template #default="s"><el-tag>{{s.row.level}}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="s">{{statusName[s.row.status]}}</template></el-table-column><el-table-column prop="contactName" label="联系人"/><el-table-column prop="contactPhone" label="电话"/><el-table-column prop="score" label="绩效评分" width="100"/></el-table></div><el-dialog v-model="dialog" title="供应商准入" width="640px"><el-form :model="form" label-width="110px"><div class="grid"><el-form-item label="供应商编码"><el-input v-model="form.code"/></el-form-item><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="统一信用代码"><el-input v-model="form.unifiedCreditCode"/></el-form-item><el-form-item label="等级"><el-select v-model="form.level"><el-option v-for="x in ['A','B','C','D']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option v-for="(v,k) in statusName" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item label="联系人"><el-input v-model="form.contactName"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="地址" style="grid-column:1/-1"><el-input v-model="form.address"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}</style>
